package com.example.mini.core;

import java.util.Objects;

/** Shared domain type. The directory says COM/Example; the package says com.example. */
public class Widget {

  private final String id;

  public Widget(String id) {
    this.id = id;
  }

  public String getId() {
    return id;
  }

  @Override
  public boolean equals(Object other) {
    return other instanceof Widget && Objects.equals(id, ((Widget) other).id);
  }
}

package com.example.mini.core;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

@Entity
@Table(name = "widget")
public class WidgetEntity {

  @Id private Long id;

  @Column(name = "display_name")
  private String displayName;

  public Long getId() {
    return id;
  }
}

package com.example.mini.core;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;

@Repository
public interface WidgetRepository extends JpaRepository<WidgetEntity, Long> {}

